inline float margin(const std::array<float, 25>& features) noexcept {
    float sum = 0.0f;
    for (size_t tree = 0; tree + 1 < tree_offsets.size(); ++tree) {
        const uint32_t offset = tree_offsets[tree];
        uint16_t index = 0;
        while (true) {
            const auto& node = nodes[offset + index];
            if (node.left == 65535) {
                sum += node.split_or_leaf;
                break;
            }
            // Frozen XGBoost uses split_type=0 and default_left=0 throughout;
            // features are finite and the condition is strictly less-than.
            index = features[node.feature] < node.split_or_leaf ? node.left : node.right;
        }
    }
    return sum;
}
